def match(orders):
    trades = []

    # Track resting orders: {price: [(arrival_time, order_id, remaining_qty), ...]}
    buy_book = {}  # prices in descending order for matching
    sell_book = {}  # prices in ascending order for matching

    # Track filled quantities and cancellations
    order_status = {}  # order_id -> {'qty': filled_qty, 'cancelled': bool}
    arrival_time_counter = 0

    for order in orders:
        arrival_time_counter += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in order_status:
                order_status[order_id]['cancelled'] = True
            # Physically remove from book
            for price in list(buy_book.keys()):
                buy_book[price] = [(t, oid, q) for t, oid, q in buy_book[price] if oid != order_id]
                if not buy_book[price]:
                    del buy_book[price]
            for price in list(sell_book.keys()):
                sell_book[price] = [(t, oid, q) for t, oid, q in sell_book[price] if oid != order_id]
                if not sell_book[price]:
                    del sell_book[price]

        else:
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            order_status[order_id] = {'qty': 0, 'cancelled': False}
            remaining_qty = qty

            if side == 'buy':
                # Match against sells
                # Sell prices in ascending order (lowest first)
                while remaining_qty > 0 and sell_book:
                    sell_prices = sorted(sell_book.keys())
                    matched = False

                    for sell_price in sell_prices:
                        # Check if we can match
                        if price is not None and sell_price > price:
                            break  # limit buy order can't match this price or higher

                        if sell_book[sell_price]:
                            # Match with earliest sell at this price
                            arrival, sell_id, sell_qty = sell_book[sell_price][0]
                            match_qty = min(remaining_qty, sell_qty)

                            trades.append([order_id, sell_id, sell_price, match_qty])

                            remaining_qty -= match_qty
                            order_status[order_id]['qty'] += match_qty
                            order_status[sell_id]['qty'] += match_qty

                            if sell_qty > match_qty:
                                # Update partial fill
                                sell_book[sell_price][0] = (arrival, sell_id, sell_qty - match_qty)
                            else:
                                # Remove filled order
                                sell_book[sell_price].pop(0)
                                if not sell_book[sell_price]:
                                    del sell_book[sell_price]

                            matched = True
                            break

                    if not matched:
                        break

                # Rest remaining qty if limit order
                if order_type == 'limit' and remaining_qty > 0:
                    if price not in buy_book:
                        buy_book[price] = []
                    buy_book[price].append((arrival_time_counter, order_id, remaining_qty))

            else:  # side == 'sell'
                # Match against buys
                # Buy prices in descending order (highest first)
                while remaining_qty > 0 and buy_book:
                    buy_prices = sorted(buy_book.keys(), reverse=True)
                    matched = False

                    for buy_price in buy_prices:
                        # Check if we can match
                        if price is not None and buy_price < price:
                            break  # limit sell order can't match this price or lower

                        if buy_book[buy_price]:
                            # Match with earliest buy at this price
                            arrival, buy_id, buy_qty = buy_book[buy_price][0]
                            match_qty = min(remaining_qty, buy_qty)

                            trades.append([buy_id, order_id, buy_price, match_qty])

                            remaining_qty -= match_qty
                            order_status[order_id]['qty'] += match_qty
